import java.util.Scanner;

// Grader test class (do not edit).
public class KiemTra {
    public static void main(String[] args) {
        String s = new Scanner(System.in).nextLine().trim();
        Member a = new Member("M001", "An");
        if (s.equals("1")) {
            Member alias = a;
